import { test, expect } from "@playwright/test";
// Node-only harness supplies a snapshot generated by the actual Apps Script publication code.
import { harness, org, course } from "./apps-script/harness.mjs";
import { DEFAULT_ADMIN_URL } from "../src/config/site";
test.use({ baseURL: "http://127.0.0.1:4173" });
function snapshot() {
  const h = harness();
  h.enable();
  h.call("saveRecord", "Organizations", org({ name: "草稿機構不得公開" }));
  const o = h.call(
    "saveRecord",
    "Organizations",
    org({ status: "published", name: "公開合作機構" }),
  ).data;
  const c = h.call(
    "saveRecord",
    "Courses",
    course({
      status: "published",
      organizationId: o.id,
      registrationStatus: "open",
      registrationUrl: "https://forms.gle/ccsaTest",
    }),
  ).data;
  const n = h.call("saveRecord", "Announcements", {
    status: "published",
    title: "正式課程公告",
    category: "課程通知",
    summary: "課程開放報名",
    content: "<script>window.injected=true</script>\n第二行內容",
    date: "2026-11-22",
    internalNotes: "不得公開的審查內容",
  }).data;
  const { createdAt, updatedAt, ...r } = h.call("listRecords", "Recruitment")
    .data[0];
  h.call("saveRecord", "Recruitment", {
    ...r,
    status: "published",
    recruitmentStatus: "open",
    startDate: "2020-01-01",
    endDate: "2099-12-31",
  });
  return { data: h.call("previewPublic").data, o, c, n };
}
test("Apps Script匯出→公開網站：機構、課程、公告、既有表單與深層連結", async ({
  page,
}) => {
  const { data, o, c, n } = snapshot();
  await page.route("**/data/content.json", (route) =>
    route.fulfill({ json: data }),
  );
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto("/seed");
    await expect(
      page.getByRole("heading", { name: "公開合作機構", exact: true }),
    ).toBeVisible();
    await expect(page.getByText("草稿機構不得公開")).toHaveCount(0);
    await expect(
      page.getByRole("link", { name: "前往Google Forms申請" }),
    ).toHaveAttribute("href", /1FAIpQLSdYOm/);
    await page.goto("/organizations/" + o.id);
    await expect(page.locator("main h1")).toHaveText("公開合作機構");
    await page.goto("/courses");
    await expect(page.locator(".course-card")).toHaveCount(1);
    await expect(page.locator(".course-card .demo-label")).toHaveCount(0);
    await page.goto("/courses/" + c.id);
    await expect(
      page.getByRole("link", { name: "前往Google Forms報名" }),
    ).toHaveAttribute("href", "https://forms.gle/ccsaTest");
    await page.reload();
    await expect(page.locator("main h1")).toHaveText("正式測試課程");
    await page.goto("/");
    await page.getByRole("link", { name: /正式課程公告/ }).click();
    await expect(page.locator("main h1")).toHaveText(n.title);
    await expect(
      page.getByText("<script>window.injected=true</script>", { exact: false }),
    ).toBeVisible();
    expect(
      await page.evaluate(() => Reflect.get(window, "injected")),
    ).toBeUndefined();
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    await expect(page.getByText("不得公開的審查內容")).toHaveCount(0);
  }
});
test("正式空資料與載入失敗不顯示示範課程，未知ID為站內404", async ({
  page,
}) => {
  await page.goto("/courses");
  await expect(page.getByText("共 0 堂課程")).toBeVisible();
  await expect(page.locator(".course-card")).toHaveCount(0);
  await page.goto("/courses/ai-basics");
  await expect(page.getByText("這條路，還沒通往未來。")).toBeVisible();
  await page.route("**/data/content.json", (route) =>
    route.fulfill({ status: 500, body: "unavailable" }),
  );
  await page.goto("/courses");
  await expect(page.getByRole("alert")).toHaveText(/暫時無法載入/);
  await expect(page.locator(".course-card")).toHaveCount(0);
});
test("含額外敏感欄位的JSON被讀取層拒絕", async ({ page }) => {
  const { data } = snapshot();
  data.organizations[0].internalNotes = "秘密";
  await page.route("**/data/content.json", (route) =>
    route.fulfill({ json: data }),
  );
  await page.goto("/seed");
  await expect(page.getByRole("alert")).toHaveText(/暫時無法載入/);
  await expect(page.getByText("公開合作機構", { exact: true })).toHaveCount(0);
});
test("有登入保護的預覽版仍能以同站登入狀態讀取公告", async ({
  page,
  context,
}) => {
  const { data, n } = snapshot();
  await context.addCookies([
    {
      name: "ccsa_preview_access",
      value: "test_access",
      url: "http://127.0.0.1:4173",
      httpOnly: true,
    },
  ]);
  await page.route("**/data/content.json", async (route) => {
    const headers = await route.request().allHeaders();
    if ((headers.cookie || "").includes("ccsa_preview_access=test_access")) {
      await route.fulfill({ json: data });
    } else {
      await route.fulfill({
        status: 401,
        contentType: "text/html; charset=utf-8",
        body: "請先登入預覽網站",
      });
    }
  });
  await page.goto("/");
  await expect(page.locator(`a[href="/announcements/${n.id}"]`)).toBeVisible();
});

test("首頁公告讀取失敗時顯示錯誤，不顯示尚無公告的提示", async ({ page }) => {
  await page.route("**/data/content.json", (route) =>
    route.fulfill({
      status: 401,
      contentType: "text/html; charset=utf-8",
      body: "請先登入預覽網站",
    }),
  );
  await page.goto("/");
  const news = page.getByRole("region", { name: "計畫新鮮事", exact: true });
  await expect(
    news.getByText("公告暫時無法載入，請稍後重新整理。", { exact: true }),
  ).toBeVisible();
  await expect(
    news.getByText("最新公告將陸續更新。", { exact: true }),
  ).toHaveCount(0);
});
test("桌機與手機的頁尾管理入口連至指定後台，且保留前台分頁", async ({
  page,
  context,
}) => {
  // Intercept the public destination to verify navigation without logging in or calling Google.
  await context.route(DEFAULT_ADMIN_URL, (route) =>
    route.fulfill({
      contentType: "text/html; charset=utf-8",
      body: "<!doctype html><html lang='zh-Hant'><title>入口測試</title><h1>測試後台入口</h1></html>",
    }),
  );
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto("/");
    await page.getByRole("link", { name: "管理入口", exact: true }).click();
    await expect(page).toHaveURL(/\/admin$/);
    await expect(page.locator("main h1")).toHaveText("計畫管理入口");
    const entry = page.getByRole("link", {
      name: "使用Google帳號前往管理後台",
      exact: true,
    });
    await expect(entry).toHaveAttribute("href", DEFAULT_ADMIN_URL);
    await expect(entry).toHaveAttribute("target", "_blank");
    const popupPromise = page.waitForEvent("popup");
    await entry.click();
    const popup = await popupPromise;
    await expect(popup).toHaveURL(DEFAULT_ADMIN_URL);
    await expect(
      popup.getByRole("heading", { name: "測試後台入口" }),
    ).toBeVisible();
    await expect(page).toHaveURL(/\/admin$/);
    await popup.close();
  }
});
